#pragma once
// Generic production auto-parser observations; all workloads and assertions are Rust-owned.
#include "chat_parser.hpp"
#include <functional>
#include <optional>

namespace prism_chat_auto {
using json=nlohmann::ordered_json;
using prism_peg::require;using prism_peg::fields;using prism_peg::string;using prism_peg::integer;
inline bool handles(const std::string & kind){return kind=="chat-helper"||kind=="chat-compare-variants"||kind=="chat-auto-trace";}
inline common_json raw(const json & value){string(value,4*1024*1024);return common_json::parse(value.get<std::string>());}
inline void validate_params(const json & value){const auto params=raw(value);require(params.is_object(),"chat template params must be object");for(const auto & item:params.items()){const auto & key=item.key();require(key=="messages"||key=="tools"||key=="add_generation_prompt"||key=="enable_thinking"||key=="extra_context","unknown chat template parameter");if(key=="add_generation_prompt"||key=="enable_thinking")require(item.value().is_boolean(),"chat template flag must be boolean");}}
inline template_params params(const json & value){const auto object=raw(value);template_params p;if(object.contains("messages"))p.messages=object.at("messages");if(object.contains("tools"))p.tools=object.at("tools");if(object.contains("add_generation_prompt"))p.add_generation_prompt=object.at("add_generation_prompt").get<bool>();if(object.contains("enable_thinking"))p.enable_thinking=object.at("enable_thinking").get<bool>();if(object.contains("extra_context"))p.extra_context=object.at("extra_context");return p;}
inline json split(const diff_split & value){return json{{"prefix",value.prefix},{"suffix",value.suffix},{"left",value.left},{"right",value.right}};}
inline json caps(const jinja::caps & c){return json{{"supports_tools",c.supports_tools},{"supports_tool_calls",c.supports_tool_calls},{"supports_system_role",c.supports_system_role},{"supports_parallel_tool_calls",c.supports_parallel_tool_calls},{"supports_preserve_reasoning",c.supports_preserve_reasoning},{"supports_reasoning_effort",c.supports_reasoning_effort},{"supports_string_content",c.supports_string_content},{"supports_typed_content",c.supports_typed_content},{"supports_object_arguments",c.supports_object_arguments}};}
inline json analysis(const autoparser::autoparser & a){
    const auto & f=a.tools.format;const auto & fun=a.tools.function;const auto & arg=a.tools.arguments;const auto & id=a.tools.call_id;
    return json{{"user_start",a.user_start},{"assistant_start",a.assistant_start},{"analysis_complete",a.analysis_complete},{"preserved_tokens",a.preserved_tokens},{"additional_stops",a.additional_stops},{"jinja_caps",caps(a.jinja_caps)},
        {"reasoning",{{"mode",static_cast<int>(a.reasoning.mode)},{"start",a.reasoning.start},{"end",a.reasoning.end}}},
        {"content",{{"mode",static_cast<int>(a.content.mode)},{"start",a.content.start},{"end",a.content.end},{"requires_nonnull_content",a.content.requires_nonnull_content}}},
        {"tools",{{"format",{{"mode",static_cast<int>(f.mode)},{"section_start",f.section_start},{"section_end",f.section_end},{"per_call_start",f.per_call_start},{"per_call_end",f.per_call_end},{"fun_name_is_key",f.fun_name_is_key},{"tools_array_wrapped",f.tools_array_wrapped},{"openai_wrapper_trigger",f.openai_wrapper_trigger},{"function_field",f.function_field},{"name_field",f.name_field},{"args_field",f.args_field},{"id_field",f.id_field},{"gen_id_field",f.gen_id_field},{"parameter_order",f.parameter_order}}},
        {"function",{{"name_prefix",fun.name_prefix},{"name_suffix",fun.name_suffix},{"args_separator",fun.args_separator},{"close",fun.close}}},
        {"arguments",{{"start",arg.start},{"end",arg.end},{"name_prefix",arg.name_prefix},{"name_suffix",arg.name_suffix},{"value_prefix",arg.value_prefix},{"value_suffix",arg.value_suffix},{"separator",arg.separator},{"tolerate_intertag_whitespace",arg.tolerate_intertag_whitespace}}},
        {"call_id",{{"pos",static_cast<int>(id.pos)},{"prefix",id.prefix},{"suffix",id.suffix}}}}}};
}
inline void validate(const json & op){
    const auto kind=op.at("Kind").get<std::string>();
    if(kind=="chat-helper") {fields(op,{"Kind","Function","Arguments"});string(op.at("Function"),64);const auto fn=op.at("Function").get<std::string>();const auto & args=op.at("Arguments");require(args.is_array(),"chat helper arguments must be array");require((fn=="calculate-diff-split"&&args.size()==2)||((fn=="until-common-prefix"||fn=="after-common-suffix")&&args.size()==3)||(fn=="segmentize-markers"&&args.size()==1),"unknown chat helper or arity");for(const auto & value:args)string(value,1024*1024);return;}
    if(kind=="chat-compare-variants") {fields(op,{"Kind","Template","BosToken","EosToken","ParametersJson","ModifierJson"});validate_params(op.at("ParametersJson"));if(!op.at("ModifierJson").is_null())validate_params(op.at("ModifierJson"));}
    else {fields(op,{"Kind","Template","BosToken","EosToken","Actions"});const auto & actions=op.at("Actions");require(actions.is_array()&&actions.size()<=128,"chat auto actions exceed bound");bool analyzed=false,built=false;for(const auto & action:actions){const auto kind=action.at("Kind").get<std::string>();if(kind=="analyze"){fields(action,{"Kind"});analyzed=true;}else if(kind=="original-caps")fields(action,{"Kind"});else if(kind=="build-parser"){fields(action,{"Kind","ParametersJson","GenerationPrompt"});require(analyzed,"chat parser requires prior analysis");const auto p=raw(action.at("ParametersJson"));require(p.is_object(),"chat generation params must be object");for(const auto & item:p.items())require(item.key()=="tools"||item.key()=="messages"||item.key()=="json_schema"||item.key()=="reasoning_format"||item.key()=="parallel_tool_calls"||item.key()=="tool_choice"||item.key()=="enable_thinking"||item.key()=="add_generation_prompt","unknown chat generation parameter");if(p.contains("reasoning_format"))require(p.at("reasoning_format").is_number_integer()&&p.at("reasoning_format").get<int>()>=0&&p.at("reasoning_format").get<int>()<=3,"invalid reasoning format");if(p.contains("tool_choice"))require(p.at("tool_choice").is_number_integer()&&p.at("tool_choice").get<int>()>=0&&p.at("tool_choice").get<int>()<=2,"invalid tool choice");for(const auto * key:{"parallel_tool_calls","enable_thinking","add_generation_prompt"})if(p.contains(key))require(p.at(key).is_boolean(),"generation flag must be boolean");string(action.at("GenerationPrompt"),65536);built=true;}else if(kind=="parse"){fields(action,{"Kind","Bytes","Flags","Map"});require(built,"chat auto parse requires prior parser");const auto & bytes=action.at("Bytes");require(bytes.is_array()&&bytes.size()<=1024*1024,"chat auto parse input exceeds bound");for(const auto & byte:bytes)integer(byte,0,255);integer(action.at("Flags"),0,3);require(action.at("Map").is_boolean(),"chat mapper flag must be boolean");}else throw std::runtime_error("unknown chat auto action");}}
    string(op.at("Template"),1024*1024);string(op.at("BosToken"),65536);string(op.at("EosToken"),65536);
}
inline json execute(const json & op){
    const auto kind=op.at("Kind").get<std::string>();
    if(kind=="chat-helper"){const auto fn=op.at("Function").get<std::string>();const auto & a=op.at("Arguments");if(fn=="calculate-diff-split")return split(calculate_diff_split(a[0].get<std::string>(),a[1].get<std::string>()));if(fn=="until-common-prefix")return json{{"value",until_common_prefix(a[0].get<std::string>(),a[1].get<std::string>(),a[2].get<std::string>())}};if(fn=="after-common-suffix")return json{{"value",after_common_suffix(a[0].get<std::string>(),a[1].get<std::string>(),a[2].get<std::string>())}};json segments=json::array();for(const auto & segment:segmentize_markers(a[0].get<std::string>()))segments.push_back(json{{"type",static_cast<int>(segment.type)},{"value",segment.value}});return json{{"segments",segments}};}
    common_chat_template tmpl(op.at("Template").get<std::string>(),op.at("BosToken").get<std::string>(),op.at("EosToken").get<std::string>());
    if(kind=="chat-compare-variants") {const auto base=params(op.at("ParametersJson"));std::function<void(template_params &)> modifier=nullptr;if(!op.at("ModifierJson").is_null()){const auto variant=params(op.at("ModifierJson"));modifier=[variant](template_params & p){p=variant;};}const auto value=autoparser::compare_variants(tmpl,base,modifier);return value?json{{"has_value",true},{"diff",split(value->diff)},{"output_A",value->output_A},{"output_B",value->output_B}}:json{{"has_value",false},{"diff",nullptr},{"output_A",nullptr},{"output_B",nullptr}};}
    autoparser::autoparser analyzer;std::optional<common_peg_arena> parser;json trace=json::array();
    for(const auto & action:op.at("Actions")){const auto kind=action.at("Kind").get<std::string>();if(kind=="analyze"){analyzer.analyze_template(tmpl);trace.push_back(json{{"analysis",analysis(analyzer)}});}else if(kind=="original-caps"){trace.push_back(json{{"caps",caps(tmpl.original_caps())}});}else if(kind=="build-parser"){const auto p=raw(action.at("ParametersJson"));autoparser::generation_params inputs;if(p.contains("tools"))inputs.tools=p.at("tools");if(p.contains("messages"))inputs.messages=p.at("messages");if(p.contains("json_schema"))inputs.json_schema=p.at("json_schema");if(p.contains("reasoning_format"))inputs.reasoning_format=static_cast<common_reasoning_format>(p.at("reasoning_format").get<int>());if(p.contains("tool_choice"))inputs.tool_choice=static_cast<common_chat_tool_choice>(p.at("tool_choice").get<int>());if(p.contains("parallel_tool_calls"))inputs.parallel_tool_calls=p.at("parallel_tool_calls").get<bool>();if(p.contains("enable_thinking"))inputs.enable_thinking=p.at("enable_thinking").get<bool>();if(p.contains("add_generation_prompt"))inputs.add_generation_prompt=p.at("add_generation_prompt").get<bool>();parser=analyzer.build_parser(inputs,action.at("GenerationPrompt").get<std::string>());trace.push_back(json::object());}else{std::string input;for(const auto & byte:action.at("Bytes"))input.push_back(static_cast<char>(byte.get<int>()));common_peg_parse_context context(input,static_cast<common_peg_parse_flags>(action.at("Flags").get<int>()));const auto result=parser->parse(context);json msg=nullptr;if(action.at("Map").get<bool>()){common_chat_msg value;common_chat_peg_mapper(value).from_ast(context.ast,result);msg=prism_chat_parser::message(value);}trace.push_back(json{{"result",prism_chat_parser::parse_result(result)},{"message",msg}});}}
    return json{{"Trace",trace}};
}
} // namespace prism_chat_auto
